package api

// The channel manager is the only place a Provider key is ever entered, so the
// page is written against three boundaries that are easy to lose in an edit:
//
//   - A key exists in the browser only as the live value of a password input.
//     It is never stored (no localStorage/sessionStorage), never placed in a
//     URL or query string, never logged, and never rendered back: the admin
//     API blanks secret_ref and returns no api_key, so a re-render after a
//     successful write cannot echo one. Every key input is cleared on success.
//   - PATCH /api/v1/admin/provider-channels/{id} replaces the whole member set
//     (app.UpdateProviderChannel assigns channel.Members from the patch), and a
//     member is matched to its stored secret by id first, label second. So the
//     add/remove affordances resend *every* surviving member with its id and
//     without api_key — that is what preserves the already-stored keys of the
//     other members. Sending only the new member would drop the rest.
//   - Two members of one channel must not share a label. A new member carrying
//     an existing member's label is matched by that label on the server, which
//     would overwrite the older member's secret before the duplicate member id
//     fails the write. The duplicate check below keeps that input out.
//   - Per-member health joins the status endpoint's MemberStatus to a config
//     member row by id: both sides carry the provider_channel_members row id,
//     so the match is exact. A member the executor filters out (disabled, or
//     no stored secret) simply has no status row and renders no health line.
const providersHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexusGate · [[i18n:providers.title]]</title><style>

.head-actions{display:flex;gap:10px}
.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.wide{grid-column:1/-1}
.cards{display:grid;gap:10px}
.panel{padding:18px}
.cardtop{display:flex;justify-content:space-between;gap:12px;align-items:center}
.card{padding:15px}
.member{margin-top:9px;padding-top:9px;border-top:1px solid var(--rule);color:var(--text-muted);font-size:12px}
.memberline{display:flex;gap:10px;align-items:center;justify-content:space-between}
.keyhead{display:flex;justify-content:space-between;align-items:center;margin:16px 0 8px}
.keyhead b{font-size:12px;font-weight:800;letter-spacing:.1em;color:var(--text-muted)}
.cardactions{display:flex;gap:8px;align-items:center}
.memberrow{border:1px solid var(--rule);border-radius:10px;background:var(--surface);padding:12px;margin-bottom:10px}
.rowtop{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}
.rowtop b{font-size:12px;color:var(--text)}
.addkey{margin-top:12px;padding-top:11px;border-top:1px solid var(--rule)}
.addform{margin-top:10px}
.advanced-config{border:1px solid var(--rule);border-radius:10px;background:var(--surface);margin-top:10px;padding:10px 12px}
.advanced-config summary{cursor:pointer;font-size:12px;font-weight:800;color:var(--text-muted);user-select:none}
.advanced-config .formgrid{grid-template-columns:1fr 1fr;gap:10px}
.provider-health{display:flex;align-items:center;gap:8px;margin:0 0 12px;min-height:16px}
.member-health{display:flex;align-items:center;gap:8px;margin-top:7px}
.member-meta{margin-top:5px;font-size:11px}
.probe-row{display:flex;gap:8px;align-items:center}
.probe-row input{flex:1}
.probe-row select{flex:1;min-width:0}
.probe-row button{white-space:nowrap}
label{display:block;font-size:12px;font-weight:800;color:var(--text-muted);margin:0 0 6px}
.empty.error{color:var(--ev-contradicted)}
@media(max-width:760px){.formgrid{grid-template-columns:1fr}
.wrap{padding:28px 18px}
}

</style></head><body><!--SHELL_HEADER--><main class="wrap"><header class="pagehead"><div><div class="eyebrow">[[i18n:providers.eyebrow]]</div><h1>[[i18n:providers.title]]</h1><p class="muted">[[i18n:providers.subtitle]]</p></div><div class="head-actions"><button type="button" class="primary" id="new-channel-btn">[[i18n:providers.newChannel]]</button><button type="button" class="ghost" id="advanced-btn">[[i18n:providers.advancedRouting]]</button><button type="button" class="ghost" id="refresh-channels">[[i18n:common.refresh]]</button></div></header><div class="auth-callout" id="auth-callout" hidden>[[i18n:providers.authCallout]]<button type="button" id="login-prompt">[[i18n:providers.loginToView]]</button></div><p class="muted">[[i18n:providers.securityNote]]</p><div class="callout callout--attention" id="admin-auth-callout" hidden><span>[[i18n:providers.adminAuthCallout]]</span></div><section class="panel"><div class="cardtop"><h2>[[i18n:providers.routing]]</h2></div><div id="routing" class="muted">[[i18n:common.loading]]</div></section><section class="panel"><div class="cardtop"><h2>[[i18n:providers.configuredChannels]]</h2><div class="tag-row"><span class="tag">[[i18n:providers.cap.video_analysis]]</span><span class="tag">[[i18n:providers.cap.asr]]</span><span class="tag">[[i18n:providers.cap.embedding]]</span><span class="tag">[[i18n:providers.cap.tag_curator]]</span><span class="tag">[[i18n:providers.cap.repurpose]]</span></div></div><p class="provider-health" id="provider-health"></p><p id="channels-status" class="muted"></p><div id="channels" class="empty">[[i18n:common.loading]]</div></section></main>
<dialog id="provider-dialog" class="ui-dialog"><button type="button" class="ui-dialog__close" data-close="provider-dialog" aria-label="[[i18n:common.close]]">×</button><h3 id="dialog-title">[[i18n:providers.newChannel]]</h3><form id="channel-form" onsubmit="saveChannel(event)"><div class="formgrid">
<div><label for="capability">[[i18n:providers.capability]]</label><select id="capability"><option value="video_analysis">[[i18n:providers.cap.video_analysis]]</option><option value="asr">[[i18n:providers.cap.asr]]</option><option value="embedding">[[i18n:providers.cap.embedding]]</option><option value="tag_curator">[[i18n:providers.cap.tag_curator]]</option><option value="repurpose">[[i18n:providers.cap.repurpose]]</option></select></div>
<div><label for="provider-name">Provider</label><select id="provider-name"></select></div>
<div class="wide callout callout--attention" id="provider-local-note" hidden>[[i18n:providers.localVlmNote]]</div>
<div><label for="label">[[i18n:providers.name]]</label><input id="label" required placeholder="[[i18n:providers.namePlaceholder]]"></div><div><label for="model">[[i18n:providers.model]]</label><div class="probe-row"><input id="model" placeholder="[[i18n:providers.modelId]]" list="model-options"><datalist id="model-options"></datalist><button type="button" class="ghost" id="probe-models" onclick="probeModels()">[[i18n:providers.probeModels]]</button></div></div>
<div><label for="route-order">[[i18n:providers.routeOrder]]</label><input id="route-order" type="number" min="0" value="0"></div><div class="wide"><label for="endpoint">[[i18n:providers.endpoint]]</label><input id="endpoint" placeholder="https://…"></div>
</div>
<div class="keyhead"><b>[[i18n:providers.memberList]]</b><button type="button" class="ghost" onclick="addMemberRow()">[[i18n:providers.addAnotherKey]]</button></div>
<div id="member-rows"><div class="memberrow"><div class="rowtop"><b>[[i18n:providers.defaultMember]]</b></div><div class="formgrid">
<div><label for="member-label">[[i18n:providers.memberLabel]]</label><input id="member-label" class="m-label" value="primary" required></div><div><label for="api-key">[[i18n:providers.apiKey]]</label><input id="api-key" class="m-key" type="password" autocomplete="new-password" required></div>
</div><details class="advanced-config wide"><summary>[[i18n:providers.advanced]]</summary><div class="formgrid"><div><label for="weight">[[i18n:providers.weight]]</label><input id="weight" aria-label="[[i18n:providers.weight]]" class="m-weight" type="number" min="1" value="1"></div><div><label for="max-inflight">[[i18n:providers.maxInflight]]</label><input id="max-inflight" aria-label="[[i18n:providers.maxInflight]]" class="m-inflight" type="number" min="1" value="1"></div></div></details>
</div></div></div>
<button type="submit">[[i18n:common.save]]</button><p id="form-status" class="muted"></p></form></dialog>
<dialog id="add-provider-dialog" class="ui-dialog"><button type="button" class="ui-dialog__close" data-close="add-provider-dialog" aria-label="[[i18n:common.close]]">×</button><h3>[[i18n:providers.addProvider]]</h3>
<div class="formgrid">
<div><label for="wizard-capability">[[i18n:providers.wizard.capability]]</label><select id="wizard-capability"><option value="video_analysis">[[i18n:providers.cap.video_analysis]]</option><option value="asr">[[i18n:providers.cap.asr]]</option></select></div>
<div><label for="wizard-provider">[[i18n:providers.wizard.provider]]</label><select id="wizard-provider"></select></div>
<div><label for="wizard-endpoint">[[i18n:providers.endpoint]]</label><input id="wizard-endpoint" placeholder="https://…"></div>
<div><label for="wizard-key">[[i18n:providers.wizard.apiKey]]</label><input id="wizard-key" type="password" autocomplete="new-password" placeholder="[[i18n:providers.pasteKey]]" required></div>
<div class="wide"><label for="wizard-model">[[i18n:providers.model]]</label><div class="probe-row"><input id="wizard-model" list="wizard-model-options" placeholder="[[i18n:providers.modelId]]"><datalist id="wizard-model-options"></datalist><button type="button" class="ghost" id="wizard-detect" onclick="wizardDetect()">[[i18n:providers.wizard.detect]]</button></div></div>
</div>
<button type="button" class="primary" id="wizard-save" onclick="wizardSave()">[[i18n:providers.wizard.save]]</button><p id="wizard-status" class="muted"></p></dialog>
<script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// The advanced provider list carries wire values only; every label renders
// through providerNameKeys (with a raw fallback), so no mixed-language string
// lives in this page. local_vlm stays here for keyed/relay deployments.
const providerOptions={video_analysis:['gemini','qwen_video','volcengine_video','local_vlm'],asr:['stepfun','qwen','volcengine_asr'],embedding:['openai_embeddings','gemini_embed_content','volc_agent_plan_embedding','volc_coding_plan_embedding'],tag_curator:['openai_chat','volc_agent_plan','volc_coding_plan'],repurpose:['openai_chat']};
// Well-known base URLs so the operator only types the key. These mirror the
// shipped config.example.json defaults; a provider with no entry leaves the
// endpoint blank (generic OpenAI-compatible, local, or account-specific).
const endpointPresets={gemini:'https://generativelanguage.googleapis.com/v1beta',gemini_embed_content:'https://generativelanguage.googleapis.com/v1beta',qwen:'https://dashscope.aliyuncs.com/compatible-mode/v1',qwen_video:'https://dashscope.aliyuncs.com/compatible-mode/v1',volcengine_video:'https://ark.cn-beijing.volces.com/api/v3',volc_agent_plan:'https://ark.cn-beijing.volces.com/api/plan/v3',volc_coding_plan:'https://ark.cn-beijing.volces.com/api/coding/v3',volc_agent_plan_embedding:'https://ark.cn-beijing.volces.com/api/plan/v3',volc_coding_plan_embedding:'https://ark.cn-beijing.volces.com/api/coding/v3',stepfun:'https://api.stepfun.com/step_plan/v1',local_vlm:'http://127.0.0.1:8080/v1',volcengine_asr:'wss://openspeech.bytedance.com/api/v3/plan/sauc/bigmodel_nostream'};
// endpointTouched separates an auto-filled preset (safe to replace when the
// provider changes) from an operator-typed endpoint (never clobbered).
let endpointTouched=false;
function applyEndpointPreset(){const provider=document.getElementById('provider-name').value;const el=document.getElementById('endpoint');if(!provider||!el||endpointTouched)return;el.value=endpointPresets[provider]||''}
function applyProviderNote(){const provider=document.getElementById('provider-name').value;const note=document.getElementById('provider-local-note');if(note)note.hidden=provider!=='local_vlm'}
// probeModels is the one-click model-list read: it sends the still-open form's
// endpoint and key to the Hub, which makes one non-billed GET {endpoint}/models
// and returns the model ids (redacted, never echoed back). The key goes no
// further than the same admin HTTPS direction it already travels on save.
function probeModels(){const status=document.getElementById('form-status');const provider=document.getElementById('provider-name').value;const endpoint=document.getElementById('endpoint').value.trim();const keyField=document.querySelector('#member-rows .memberrow .m-key');const key=keyField?keyField.value.trim():'';if(!endpoint){status.textContent=tdT('providers.probeNeedEndpoint');return}if(!key){status.textContent=tdT('providers.probeNeedKey');return}status.textContent=tdT('providers.probeInProgress');fetch('/api/v1/admin/provider-channels/probe-models',{method:'POST',headers:adminHeaders(true),body:JSON.stringify({provider_name:provider,endpoint:endpoint,api_key:key})}).then(json).then(function(d){const dl=document.getElementById('model-options');dl.innerHTML=(d.models||[]).map(m=>'<option value="'+esc(m)+'"></option>').join('');const model=document.getElementById('model');if(d&&d.models&&d.models.length){if(!model.value.trim())model.value=d.models[0];status.textContent=tdPlural('providers.probeFound',d.models.length)}else{status.textContent='✗ '+((d&&d.message)||tdT('providers.probeNoModels'))}}).catch(function(e){status.textContent='✗ '+e.message})}
// capKeys is the capability value -> catalog-key table. Wire values
// (video_analysis/asr/embedding/tag_curator/repurpose) never become catalog
// keys by concatenation; capName resolves them and falls back to the raw value.
const capKeys={video_analysis:'providers.cap.video_analysis',asr:'providers.cap.asr',embedding:'providers.cap.embedding',tag_curator:'providers.cap.tag_curator',repurpose:'providers.cap.repurpose'};
function capName(cap){return tdT(capKeys[cap]||cap)}
// --- Beginner wizard: choose ONE capability, then one of its grounded presets.
// Each preset carries a known endpoint and default model, so the operator only
// types the key. Model detection is optional: a successful probe fills the
// datalist without overwriting typed input; unprobeable/no_models/schema_unknown
// keep the editable preset and explain that detection is unavailable; only a
// key_invalid probe blocks saving. One submit creates exactly one channel and
// clears the key. A 401/403 opens the shared admin prompt. local_vlm is not a
// beginner choice (channel execution needs a stored secret reference); it stays
// in the advanced provider list with the provider-local-note guidance.
const wizardPresets={video_analysis:[['gemini','gemini_generate_content','gemini-2.5-flash'],['qwen_video','openai_video','qwen3.6-flash'],['volcengine_video','openai_video','doubao-1.5-vision-pro-250428']],asr:[['stepfun','','stepaudio-2.5-asr'],['qwen','','qwen3-asr-flash'],['volcengine_asr','','doubao-seed-asr-2.0']]};
let wizardProbeStatus='';
const providerNameKeys={gemini:'providers.provider.gemini',qwen_video:'providers.provider.qwen_video',volcengine_video:'providers.provider.volcengine_video',local_vlm:'providers.provider.local_vlm',stepfun:'providers.provider.stepfun',qwen:'providers.provider.qwen',volcengine_asr:'providers.provider.volcengine_asr',openai_embeddings:'providers.provider.openai_embeddings',gemini_embed_content:'providers.provider.gemini_embed_content',volc_agent_plan_embedding:'providers.provider.volc_agent_plan_embedding',volc_coding_plan_embedding:'providers.provider.volc_coding_plan_embedding',openai_chat:'providers.provider.openai_chat',volc_agent_plan:'providers.provider.volc_agent_plan',volc_coding_plan:'providers.provider.volc_coding_plan'};
function wizardModelPreset(){const cap=document.getElementById('wizard-capability').value;const provider=document.getElementById('wizard-provider').value;const entry=(wizardPresets[cap]||[]).find(function(x){return x[0]===provider});return entry?entry[2]:''}
function syncWizardProviders(){const cap=document.getElementById('wizard-capability').value;const select=document.getElementById('wizard-provider');const prior=select.value;select.innerHTML=(wizardPresets[cap]||[]).map(function(x){return '<option value="'+esc(x[0])+'">'+esc(tdT(providerNameKeys[x[0]]||x[0]))+'</option>'}).join('');if([...select.options].some(function(o){return o.value===prior}))select.value=prior;wizardSelectProvider()}
function openAddProviderDialog(){document.getElementById('wizard-key').value='';document.getElementById('wizard-status').textContent='';document.getElementById('wizard-status').className='muted';wizardProbeStatus='';syncWizardProviders();openDialog('add-provider-dialog',document.getElementById('new-channel-btn'),'#wizard-capability')}
function wizardSelectProvider(){const provider=document.getElementById('wizard-provider').value;const el=document.getElementById('wizard-endpoint');if(el)el.value=endpointPresets[provider]||'';const model=document.getElementById('wizard-model');if(model){model.value=wizardModelPreset()||'';model.dataset.preset=model.value}const dl=document.getElementById('wizard-model-options');if(dl)dl.innerHTML='';wizardProbeStatus=''}
async function wizardDetect(){const status=document.getElementById('wizard-status');const provider=document.getElementById('wizard-provider').value;const endpoint=document.getElementById('wizard-endpoint').value.trim();const key=document.getElementById('wizard-key').value.trim();if(!endpoint){status.textContent=tdT('providers.probeNeedEndpoint');return}if(!key){status.textContent=tdT('providers.probeNeedKey');return}status.textContent=tdT('providers.probeInProgress');try{const r=await fetch('/api/v1/admin/provider-channels/probe-models',{method:'POST',headers:adminHeaders(true),body:JSON.stringify({provider_name:provider,endpoint:endpoint,api_key:key})});if(r.status===401||r.status===403){openAdminDialog();status.textContent=tdT('common.loginRequiredTop');return}const d=await json(r);const dl=document.getElementById('wizard-model-options');wizardProbeStatus=(d&&d.status)||'';const models=(d&&d.models)||[];if(models.length){dl.innerHTML=models.map(function(m){return '<option value="'+esc(m)+'"></option>'}).join('');status.className='muted';status.textContent=tdPlural('providers.probeFound',models.length);return}status.className='callout';if(wizardProbeStatus==='key_invalid'){status.className='callout callout--contradicted';status.textContent=tdT('providers.wizard.keyInvalid',{message:(d&&d.message)||''})}else if(wizardProbeStatus==='unprobeable'){status.textContent=tdT('providers.wizard.probeUnavailable')}else if(wizardProbeStatus==='no_models'){status.textContent=tdT('providers.wizard.probeNoModels')}else{status.textContent=tdT('providers.wizard.probeSchemaUnknown')}}catch(e){status.className='callout';status.textContent='✗ '+e.message}}
async function wizardSave(){const status=document.getElementById('wizard-status');status.className='muted';const cap=document.getElementById('wizard-capability').value;const provider=document.getElementById('wizard-provider').value;const endpoint=document.getElementById('wizard-endpoint').value.trim();const model=document.getElementById('wizard-model').value.trim();const key=document.getElementById('wizard-key').value.trim();if(!endpoint){status.textContent=tdT('providers.probeNeedEndpoint');return}if(!key){status.textContent=tdT('providers.probeNeedKey');return}if(!model){status.textContent=tdT('providers.probeNeedModel');return}if(wizardProbeStatus==='key_invalid'){status.className='callout callout--contradicted';status.textContent=tdT('providers.wizard.keyInvalid',{message:''});return}status.textContent=tdT('providers.saving');const body={capability:cap,label:capName(cap),provider_name:provider,endpoint:endpoint,model:model,enabled:true,route_order:0,members:[{label:'primary',api_key:key,enabled:true,weight:1,max_inflight:1}]};try{const r=await fetch('/api/v1/admin/provider-channels',{method:'POST',headers:adminHeaders(true),body:JSON.stringify(body)});if(r.status===401||r.status===403){openAdminDialog();status.textContent=tdT('common.loginRequiredTop');return}await json(r);document.getElementById('wizard-key').value='';status.textContent=tdT('providers.saved');closeDialog('add-provider-dialog');await loadChannels();channelStatus(tdT('providers.saved'))}catch(e){status.textContent=tdT('providers.saveError',{message:e.message})}}


let channelCache=[];let statusCache=[];let channelHealth=new Map();let anyRuntimeData=false;
function syncProviderOptions(){const capability=document.getElementById('capability').value;const select=document.getElementById('provider-name');const prior=select.value;select.innerHTML=(providerOptions[capability]||[]).map((value)=>'<option value="'+esc(value)+'">'+esc(tdT(providerNameKeys[value]||value))+'</option>').join('');if([...select.options].some(o=>o.value===prior))select.value=prior;applyEndpointPreset();applyProviderNote()}
 function csrfToken(){const prefix='__Host-nexusgate_csrf=';const item=document.cookie.split('; ').find(function(x){return x.indexOf(prefix)===0});return item?decodeURIComponent(item.slice(prefix.length)):''}
 function adminHeaders(json=false){const headers={};const csrf=csrfToken();if(csrf)headers['X-CSRF-Token']=csrf;if(json)headers['Content-Type']='application/json';return headers}
async function json(r){if(!r.ok)throw Error(await tdApiErrorMessage(r));return r.status===204?null:r.json()}
function duplicateLabel(labels){const seen=new Set();for(const raw of labels){const key=String(raw||'').trim().toLowerCase();if(!key)continue;if(seen.has(key))return raw;seen.add(key)}return ''}
 function keyFields(prefix){return '<div class="formgrid"><div><label>'+esc(tdT('providers.memberLabel'))+'</label><input class="'+prefix+'label" aria-label="'+esc(tdT('providers.memberLabel'))+'" value="" required></div><div><label>'+esc(tdT('providers.apiKey'))+'</label><input class="'+prefix+'key" aria-label="'+esc(tdT('providers.apiKey'))+'" type="password" autocomplete="new-password" required></div></div><details class="advanced-config wide"><summary>'+esc(tdT('providers.advanced'))+'</summary><div class="formgrid"><div><label>'+esc(tdT('providers.weight'))+'</label><input class="'+prefix+'weight" aria-label="'+esc(tdT('providers.weight'))+'" type="number" min="1" value="1"></div><div><label>'+esc(tdT('providers.maxInflight'))+'</label><input class="'+prefix+'inflight" aria-label="'+esc(tdT('providers.maxInflight'))+'" type="number" min="1" value="1"></div></div></details>'}
function addMemberRow(){const rows=document.getElementById('member-rows');const row=document.createElement('div');row.className='memberrow';row.innerHTML='<div class="rowtop"><b>'+esc(tdT('providers.addedKeyLabel'))+'</b><button type="button" class="danger rowremove">'+esc(tdT('providers.removeRow'))+'</button></div>'+keyFields('m-');rows.appendChild(row);const label=row.querySelector('.m-label');label.value='key-'+rows.children.length;row.querySelector('.rowremove').addEventListener('click',()=>row.remove());label.focus()}
function formMembers(){return [...document.querySelectorAll('#member-rows .memberrow')].map(row=>({label:row.querySelector('.m-label').value.trim(),api_key:row.querySelector('.m-key').value.trim(),enabled:true,weight:Number(row.querySelector('.m-weight').value)||1,max_inflight:Number(row.querySelector('.m-inflight').value)||1}))}
function clearFormKeys(){document.querySelectorAll('#member-rows .m-key').forEach(input=>{input.value=''});[...document.querySelectorAll('#member-rows .memberrow')].slice(1).forEach(row=>row.remove())}
function memberPatches(channel){return (channel.members||[]).map(m=>({id:m.id,label:m.label,enabled:m.enabled!==false,weight:Number(m.weight)||1,max_inflight:Number(m.max_inflight)||1}))}
function channelStatus(text){document.getElementById('channels-status').textContent=text}
async function loadProviderHealth(){const el=document.getElementById('provider-health');if(!el)return;statusCache=[];channelHealth=new Map();anyRuntimeData=false;try{const r=await fetch('/api/v1/admin/provider-channels/status',{headers:adminHeaders()});if(!r.ok){el.innerHTML='';return}const caps=await r.json();const list=Array.isArray(caps)?caps:[];statusCache=list;const chm=new Map();let anyData=false;list.forEach(c=>{if(!c||!c.has_runtime_data)return;anyData=true;if(!c.snapshot||!Array.isArray(c.snapshot.channels))return;c.snapshot.channels.forEach(ch=>{if(!ch)return;const members=new Map();(ch.members||[]).forEach(mm=>{if(mm&&mm.id)members.set(mm.id,mm)});chm.set(ch.id,members)})});anyRuntimeData=anyData;channelHealth=chm;let ok=0,degraded=0;list.forEach(c=>{if(!c||!c.has_runtime_data||!c.snapshot||!Array.isArray(c.snapshot.channels))return;c.snapshot.channels.forEach(ch=>{if(!ch||!ch.enabled)return;if(ch.available)ok++;else degraded++})});if(!anyData||ok+degraded===0){el.innerHTML='<span class="muted">'+esc(tdT('providers.noUsage'))+'</span>'}else if(degraded>0){el.innerHTML='<span class="pill bad">'+esc(tdT('providers.degraded'))+'</span>'}else{el.innerHTML='<span class="pill ok">'+esc(tdT('providers.healthy'))+'</span>'}}catch(e){el.innerHTML=''}}
async function patchMembers(id,members){return fetch('/api/v1/admin/provider-channels/'+encodeURIComponent(id),{method:'PATCH',headers:adminHeaders(true),body:JSON.stringify({members})}).then(json)}
function fmtHealthTime(v){const t=new Date(v);return isNaN(t.getTime())?String(v||''):tdFormatDateTime(t)}
function memberHealth(s){if(s.retired)return'<span class="pill bad">'+esc(tdT('status.disabled'))+'</span>';const cooling=!!s.half_open||(s.cooldown_until&&new Date(s.cooldown_until).getTime()>Date.now());if(cooling){const t=s.cooldown_until?fmtHealthTime(s.cooldown_until):'';return'<span class="pill warn">'+esc(tdT('providers.cooling')+(t?' · '+t:''))+'</span>'}if(!(Number(s.failures)||0))return'<span class="pill ok">'+esc(tdT('status.healthy'))+'</span>';if(s.last_failure_retryable)return'<span class="pill warn">'+esc(tdT('providers.recentFailureRetryable'))+'</span>';return'<span class="pill bad">'+esc(tdT('providers.recentFailure'))+'</span>'}
function healthMeta(s){const t=s.last_success_at?fmtHealthTime(s.last_success_at):tdT('providers.noRecord');return esc(tdT('providers.metaSuccess',{n:Number(s.successes)||0}))+' · '+esc(tdT('providers.metaFailures',{n:Number(s.failures)||0}))+' · '+esc(tdT('providers.metaRateLimited',{n:Number(s.retryable_429)||0}))+' · '+esc(tdT('providers.metaServerError',{n:Number(s.server_error_5xx)||0}))+' · '+esc(tdT('providers.metaLatency',{n:Number(s.latency_ms)||0}))+' · '+esc(tdT('providers.metaLastSuccess',{time:t}))}
function memberHealthRow(c,m){const ch=channelHealth.get(c.id);if(!anyRuntimeData)return'<div class="member-health muted">'+esc(tdT('providers.noUsage'))+'</div>';if(!ch)return'';const s=ch.get(m.id);if(!s)return'';return'<div class="member-health">'+memberHealth(s)+'</div><div class="member-meta muted">'+healthMeta(s)+'</div>'}
function renderRouting(items){const el=document.getElementById('routing');if(!el)return;const caps=['video_analysis','asr','embedding','tag_curator','repurpose'];const lines=caps.map(function(cap){const list=(items||[]).filter(function(c){return c.capability===cap&&c.enabled}).sort(function(a,b){return (a.route_order||0)-(b.route_order||0)});if(!list.length)return null;const chain=list.map(function(c,i){return (i===0?'':' → ')+esc(c.label||c.provider_name)}).join('');return '<div class="kv"><span class="k">'+esc(tdT(capKeys[cap]||cap))+'</span><span class="v">'+chain+'</span></div>'}).filter(Boolean);el.innerHTML=lines.length?lines.join(''):'<span class="muted">'+esc(tdT('providers.noEnabledChannels'))+'</span>'}function renderChannels(items){channelCache=items;const el=document.getElementById('channels');if(!items.length){el.className='empty';el.innerHTML='<p class="muted">'+esc(tdT('providers.noChannels'))+'</p><button type="button" class="primary" onclick="openAddProviderDialog()">'+esc(tdT('providers.addProvider'))+'</button>';return}el.className='cards';el.innerHTML=items.map(c=>'<article class="card" data-channel="'+esc(c.id)+'"><div class="cardtop"><div><b>'+esc(c.label)+'</b><div class="muted">'+esc(tdT(capKeys[c.capability]||c.capability))+' · '+esc(c.provider_name)+' · '+esc(c.model||tdT('providers.noModelSelected'))+'</div></div><div class="cardactions"><span class="pill '+(c.enabled?'ok':'bad')+'">'+esc(tdT(c.enabled?'status.enabled':'status.disabled'))+'</span><button type="button" class="ghost" data-act="test-channel">'+esc(tdT('providers.testChannel'))+'</button><button type="button" class="ghost" data-act="edit-channel">'+esc(tdT('common.edit'))+'</button><button type="button" class="ghost" data-act="toggle-channel">'+esc(tdT(c.enabled?'providers.disable':'providers.enable'))+'</button><button type="button" class="ghost danger" data-act="delete-channel">'+esc(tdT('common.delete'))+'</button></div></div><p class="muted" id="test-result-'+esc(c.id)+'"></p>'+(c.members||[]).map(m=>'<div class="member"><div class="memberline"><span>'+esc(m.label)+' · '+esc(tdT('providers.memberPriority',{weight:Number(m.weight||1)}))+' · '+esc(tdT('providers.memberInflight',{n:Number(m.max_inflight||1)}))+' · '+esc(tdT(m.secret_ready?'providers.keyStored':'providers.keyMissing'))+'</span><button type="button" class="danger" data-act="remove-member" data-member="'+esc(m.id)+'">'+esc(tdT('common.remove'))+'</button></div>'+memberHealthRow(c,m)+'</div>').join('')+'<div class="addkey"><button type="button" class="ghost" data-act="toggle-add">'+esc(tdT('providers.addKey'))+'</button><div class="addform" hidden>'+keyFields('a-')+'<button type="button" data-act="save-key">'+esc(tdT('providers.storeKey'))+'</button> <button type="button" class="ghost" data-act="cancel-key">'+esc(tdT('common.cancel'))+'</button></div><p class="muted cardstatus"></p></div></article>').join('')}
async function loadChannels(){channelStatus('');await loadProviderHealth();try{const items=await fetch('/api/v1/admin/provider-channels',{headers:adminHeaders()}).then(json);renderChannels(items||[]);renderRouting(items||[])}catch(e){channelCache=[];const el=document.getElementById('channels');el.className='empty error';el.textContent=tdT('providers.loadError',{message:e.message})}}
let editingId=null;
async function saveChannel(event){event.preventDefault();const status=document.getElementById('form-status');const members=formMembers();const dup=duplicateLabel(members.map(m=>m.label));if(dup){status.textContent=tdT('providers.duplicateLabel',{label:dup});return}status.textContent=tdT('providers.saving');if(editingId){await saveChannelPatch(status,members);return}const body={capability:document.getElementById('capability').value,label:document.getElementById('label').value.trim(),provider_name:document.getElementById('provider-name').value,endpoint:document.getElementById('endpoint').value.trim(),model:document.getElementById('model').value.trim(),enabled:true,route_order:Number(document.getElementById('route-order').value)||0,members};try{await fetch('/api/v1/admin/provider-channels',{method:'POST',headers:adminHeaders(true),body:JSON.stringify(body)}).then(json);clearFormKeys();status.textContent=tdT('providers.saved');await loadChannels()}catch(e){status.textContent=tdT('providers.saveError',{message:e.message})}}
async function testChannel(card,channel){const el=document.getElementById('test-result-'+channel.id);if(!el)return;el.textContent=tdT('providers.testing');try{const r=await fetch('/api/v1/admin/provider-channels/'+encodeURIComponent(channel.id)+'/test',{method:'POST',headers:adminHeaders()});const d=await json(r);if(d&&d.model_responded){el.textContent=tdT('providers.testOk',{model:d.model_name||tdT('providers.unknownModel'),latency:Number(d.latency_ms)||0})}else{el.textContent='✗ '+((d&&d.message)||tdT('providers.testFailed'))}}catch(e){el.textContent='✗ '+e.message}}
async function addChannelKey(card,channel){const form=card.querySelector('.addform');const status=card.querySelector('.cardstatus');const label=form.querySelector('.a-label').value.trim();const key=form.querySelector('.a-key').value.trim();if(!label||!key){status.textContent=tdT('providers.addKeyNeedFields');return}const members=memberPatches(channel);const dup=duplicateLabel(members.map(m=>m.label).concat([label]));if(dup){status.textContent=tdT('providers.duplicateLabel',{label:dup});return}members.push({label,api_key:key,enabled:true,weight:Number(form.querySelector('.a-weight').value)||1,max_inflight:Number(form.querySelector('.a-inflight').value)||1});status.textContent=tdT('providers.savingKey');try{await patchMembers(channel.id,members);form.querySelector('.a-key').value='';await loadChannels();channelStatus(tdT('providers.keyWritten',{label}))}catch(e){status.textContent=tdT('providers.addKeyError',{message:e.message})}}
async function removeChannelKey(card,channel,memberID){const status=card.querySelector('.cardstatus');const members=memberPatches(channel).filter(m=>m.id!==memberID);if(!members.length){status.textContent=tdT('providers.removeLastKeyBlocked');return}if(!confirm(tdT('providers.removeKeyConfirm')))return;status.textContent=tdT('providers.removingKey');try{await patchMembers(channel.id,members);await loadChannels();channelStatus(tdT('providers.keyRemoved'))}catch(e){status.textContent=tdT('providers.removeKeyError',{message:e.message})}}
// --- management ---
function openDialog(id,opener,focus){tdOpenSurface(id,opener,focus)}
function closeDialog(id){tdCloseSurface(id)}
function openCreate(){editingId=null;const form=document.getElementById('channel-form');form.reset();endpointTouched=false;document.getElementById('capability').disabled=false;document.getElementById('dialog-title').textContent=tdT('providers.newChannel');applyEndpointPreset();applyProviderNote();openDialog('provider-dialog',document.getElementById('advanced-btn'),'#label')}
function openEdit(id,opener){const c=(channelCache||[]).find(x=>x.id===id);if(!c)return;editingId=id;endpointTouched=true;document.getElementById('dialog-title').textContent=tdT('providers.editChannel');document.getElementById('capability').value=c.capability;document.getElementById('capability').disabled=true;document.getElementById('provider-name').value=c.provider_name||'';document.getElementById('label').value=c.label||'';document.getElementById('endpoint').value=c.endpoint||'';document.getElementById('model').value=c.model||'';document.getElementById('route-order').value=c.route_order||0;syncProviderOptions();const form=document.getElementById('channel-form');const rows=form.querySelectorAll('.memberrow');rows.forEach(function(r,i){if(i>0)r.remove()});const members=c.members||[];const keyRow=form.querySelector('.memberrow');keyRow.querySelector('.m-label').value=members[0]?members[0].label:'primary';const firstKey=keyRow.querySelector('.m-key');firstKey.value='';firstKey.placeholder=tdT('providers.keepExistingKey');if(members[0])keyRow.dataset.memberId=members[0].id;members.slice(1).forEach(function(m){addMemberRow();const rs=form.querySelectorAll('.memberrow');const row=rs[rs.length-1];row.querySelector('.m-label').value=m.label||'';const k=row.querySelector('.m-key');k.value='';k.placeholder=tdT('providers.keepExistingKey')});openDialog('provider-dialog',opener,'#label')}
async function saveChannelPatch(status,members){const c=(channelCache||[]).find(x=>x.id===editingId)||{};const patch={};if(document.getElementById('label').value.trim()!==c.label)patch.label=document.getElementById('label').value.trim();if(document.getElementById('provider-name').value!==c.provider_name)patch.provider_name=document.getElementById('provider-name').value;if(document.getElementById('endpoint').value.trim()!==c.endpoint)patch.endpoint=document.getElementById('endpoint').value.trim();if(document.getElementById('model').value.trim()!==(c.model||''))patch.model=document.getElementById('model').value.trim();if((Number(document.getElementById('route-order').value)||0)!==(c.route_order||0))patch.route_order=Number(document.getElementById('route-order').value)||0;const memberIds=(c.members||[]).map(x=>x.id);const mChanges=members.some(function(m,i){const orig=c.members&&c.members[i];return !orig||orig.label!==m.label||(m.api_key&&m.api_key.length>0)});if(mChanges){patch.members=members.map(function(m,i){return {id:memberIds[i]||'',label:m.label,api_key:m.api_key}})}try{await fetch('/api/v1/admin/provider-channels/'+encodeURIComponent(editingId),{method:'PATCH',headers:adminHeaders(true),body:JSON.stringify(patch)}).then(json);closeDialog('provider-dialog');loadChannels()}catch(e){status.textContent=tdT('providers.saveError',{message:e.message})}}
async function toggleChannel(id){const c=(channelCache||[]).find(x=>x.id===id);if(!c)return;const action=c.enabled?'disable':'enable';try{await fetch('/api/v1/admin/provider-channels/'+encodeURIComponent(id)+'/'+action,{method:'POST',headers:adminHeaders()}).then(json);loadChannels()}catch(e){alert(tdT(action==='disable'?'providers.disableError':'providers.enableError',{message:e.message}))}}
async function deleteChannel(id){const c=(channelCache||[]).find(x=>x.id===id);if(!c)return;if(!confirm(tdT('providers.deleteConfirm',{label:c.label})))return;try{await fetch('/api/v1/admin/provider-channels/'+encodeURIComponent(id),{method:'DELETE',headers:adminHeaders()}).then(json);loadChannels()}catch(e){alert(tdT('providers.deleteError',{message:e.message}))}}
document.getElementById('channels').addEventListener('click',function(e){const btn=e.target.closest('[data-act]');if(!btn)return;const card=btn.closest('[data-channel]'),cid=card&&card.dataset.channel;if(!cid)return;const act=btn.dataset.act;const channel=(channelCache||[]).find(x=>x.id===cid);if(act==='edit-channel')openEdit(cid);else if(act==='toggle-channel')toggleChannel(cid);else if(act==='delete-channel')deleteChannel(cid);else if(act==='test-channel')testChannel(card,channel);else if(act==='toggle-add'){const f=card.querySelector('.addform');if(f){f.hidden=false;f.querySelector('.a-label').focus()}}else if(act==='cancel-key'){const f=card.querySelector('.addform');if(f){f.hidden=true;card.querySelector('.cardstatus').textContent=''}}else if(act==='save-key'){addChannelKey(card,channel)}else if(act==='remove-member'){removeChannelKey(card,channel,btn.dataset.member)}});
document.getElementById('new-channel-btn').addEventListener('click',openAddProviderDialog);
document.getElementById('advanced-btn').addEventListener('click',openCreate);
document.getElementById('refresh-channels').addEventListener('click',loadChannels);
document.querySelectorAll('[data-close="provider-dialog"]').forEach(function(b){b.addEventListener('click',function(){closeDialog('provider-dialog')})});
document.querySelectorAll('[data-close="add-provider-dialog"]').forEach(function(b){b.addEventListener('click',function(){closeDialog('add-provider-dialog')})});
document.getElementById('wizard-capability').addEventListener('change',syncWizardProviders);
document.getElementById('wizard-provider').addEventListener('change',wizardSelectProvider);
document.getElementById('wizard-key').addEventListener('input',function(){wizardProbeStatus='';const s=document.getElementById('wizard-status');if(s)s.className='muted'});
document.getElementById('capability').addEventListener('change',syncProviderOptions);syncProviderOptions();
document.getElementById('provider-name').addEventListener('change',function(){applyEndpointPreset();applyProviderNote()});
document.getElementById('endpoint').addEventListener('input',function(){endpointTouched=true});
loadChannels();window.addEventListener('nexusgate:admin-auth-changed',loadChannels);

document.getElementById('login-prompt').addEventListener('click',openAdminDialog);
window.addEventListener('nexusgate:admin-auth-changed',function(){const state=fetch('/api/v1/auth/admin/session').then(function(r){document.getElementById('auth-callout').hidden=r.ok})});
</script></body></html>`
